return {["en"]={["mod"]="vehicle_specified_seat_switch",["language"]="en",["strings"]={["mode"]="Variant",["normal"]="Normal",["enhanced"]="Enhanced",["strategy"]="Key strategy",["mode_description"]="Normal uses native seat groups. Enhanced also switches across groups in solo and multiplayer. Changes apply after the current switch finishes.",["keys_description"]="INI and menu bindings are independent. Menu bindings start unbound: assign them on the MODS binding tab. Switching strategy never overwrites either configuration.",["hint"]="INI active. Set Key strategy to ModBindingsMenu to use these bindings.",["seat1"]="Seat 1: Driver",["seat2"]="Seat 2: Front passenger / Gunner",["seat3"]="Seat 3: Rear left / Left passenger / Flamer",["seat4"]="Seat 4: Rear right / Right passenger",["seat5"]="Seat 5: M-102 machine gunner"}},["bundled"]={["zh-Hans"]={["mod"]="vehicle_specified_seat_switch",["language"]="zh-Hans",["strings"]={["mode"]="版本选择",["normal"]="普通版",["enhanced"]="加强版",["strategy"]="按键策略",["mode_description"]="普通版保留原有座位分组；加强版支持单人、多人跨区换座。当前换座完成后应用新设置。",["keys_description"]="INI 与菜单按键独立保存、互不覆盖。菜单按键初始未绑定，请到 MODS 按键页设置。可随时切换生效来源。",["hint"]="当前生效的为VehicleSeatSwitch.ini配置，若要使用下列设置请将“按键策略”改为“ModBindingsMenu”。",["seat1"]="座位1：驾驶位",["seat2"]="座位2：副驾／炮位",["seat3"]="座位3：后左／左乘员／喷火",["seat4"]="座位4：后右／右乘员",["seat5"]="座位5：M-102机枪位"}},["zh-Hant"]={["mod"]="vehicle_specified_seat_switch",["language"]="zh-Hant",["strings"]={["mode"]="版本選擇",["normal"]="普通版",["enhanced"]="加強版",["strategy"]="按鍵策略",["mode_description"]="普通版保留原有座位分組；加強版支援單人、多人跨區換座。目前換座完成後套用新設定。",["keys_description"]="INI 與選單按鍵獨立儲存、互不覆寫。選單按鍵起初未綁定，請到 MODS 按鍵頁設定。可隨時切換生效來源。",["hint"]="目前使用VehicleSeatSwitch.ini設定；如要使用下列設定，請將「按鍵策略」改為「ModBindingsMenu」。",["seat1"]="座位1：駕駛位",["seat2"]="座位2：副駕／炮位",["seat3"]="座位3：後左／左乘員／噴火",["seat4"]="座位4：後右／右乘員",["seat5"]="座位5：M-102機槍位"}},["ja"]={["mod"]="vehicle_specified_seat_switch",["language"]="ja",["strings"]={["mode"]="バージョン選択",["normal"]="通常版",["enhanced"]="強化版",["strategy"]="キー設定の選択",["mode_description"]="通常版は元の座席グループ内で移動します。強化版はソロとマルチでグループを越えて移動できます。座席移動の完了後に変更を適用します。",["keys_description"]="INI とメニューの設定は独立しています。メニューの初期割り当ては空です。MODS キー設定で割り当ててください。切り替えても上書きしません。",["hint"]="INI が有効です。この設定を使うには「キー設定の選択」を ModBindingsMenu に変更してください。",["seat1"]="座席1：運転席",["seat2"]="座席2：助手席／砲手",["seat3"]="座席3：左後部／左乗員／火炎放射器",["seat4"]="座席4：右後部／右乗員",["seat5"]="座席5：M-102 機銃手"}},["ko"]={["mod"]="vehicle_specified_seat_switch",["language"]="ko",["strings"]={["mode"]="버전 선택",["normal"]="일반판",["enhanced"]="강화판",["strategy"]="키 설정 방식",["mode_description"]="일반판은 기존 좌석 그룹을 유지합니다. 강화판은 싱글 및 멀티플레이에서 그룹 간 이동을 지원합니다. 현재 좌석 이동이 끝난 후 적용됩니다.",["keys_description"]="INI와 메뉴 설정은 별도로 저장됩니다. 메뉴 키는 처음에 미지정 상태입니다. MODS 키 설정에서 지정하세요. 방식을 바꿔도 다른 설정을 덮어쓰지 않습니다.",["hint"]="INI 사용 중입니다. 아래 설정을 사용하려면 키 설정 방식을 ModBindingsMenu로 바꾸세요.",["seat1"]="좌석 1: 운전석",["seat2"]="좌석 2: 조수석 / 포수",["seat3"]="좌석 3: 뒤 왼쪽 / 왼쪽 승객 / 화염방사기",["seat4"]="좌석 4: 뒤 오른쪽 / 오른쪽 승객",["seat5"]="좌석 5: M-102 기관총 사수"}},["fr"]={["mod"]="vehicle_specified_seat_switch",["language"]="fr",["strings"]={["mode"]="Version",["normal"]="Normale",["enhanced"]="Améliorée",["strategy"]="Source des touches",["mode_description"]="Normale conserve les groupes de sièges. Améliorée permet de changer de groupe en solo et en multijoueur. Les changements attendent la fin du déplacement en cours.",["keys_description"]="Les réglages INI et du menu sont indépendants. Les touches du menu sont initialement libres : configurez-les dans MODS. Changer de source ne remplace aucun réglage.",["hint"]="INI actif. Choisissez ModBindingsMenu dans Source des touches pour utiliser ces réglages.",["seat1"]="Siège 1 : conducteur",["seat2"]="Siège 2 : passager avant / tireur",["seat3"]="Siège 3 : arrière gauche / passager gauche / lance-flammes",["seat4"]="Siège 4 : arrière droit / passager droit",["seat5"]="Siège 5 : mitrailleur du M-102"}},["de"]={["mod"]="vehicle_specified_seat_switch",["language"]="de",["strings"]={["mode"]="Version",["normal"]="Normal",["enhanced"]="Erweitert",["strategy"]="Tastenquelle",["mode_description"]="Normal behält die Sitzgruppen des Spiels bei. Erweitert erlaubt Gruppenwechsel im Einzel- und Mehrspielermodus. Änderungen gelten nach dem laufenden Sitzwechsel.",["keys_description"]="INI und Menü speichern ihre Belegung unabhängig. Menütasten sind anfangs unbelegt: im MODS-Reiter zuweisen. Ein Quellenwechsel überschreibt keine Belegung.",["hint"]="INI aktiv. Für diese Belegung Tastenquelle auf ModBindingsMenu stellen.",["seat1"]="Sitz 1: Fahrer",["seat2"]="Sitz 2: Beifahrer / Schütze",["seat3"]="Sitz 3: hinten links / linker Passagier / Flammenwerfer",["seat4"]="Sitz 4: hinten rechts / rechter Passagier",["seat5"]="Sitz 5: M-102-MG-Schütze"}},["it"]={["mod"]="vehicle_specified_seat_switch",["language"]="it",["strings"]={["mode"]="Versione",["normal"]="Normale",["enhanced"]="Potenziata",["strategy"]="Fonte dei tasti",["mode_description"]="Normale mantiene i gruppi di posti originali. Potenziata permette di cambiare gruppo in singolo e multigiocatore. Le modifiche attendono la fine del cambio in corso.",["keys_description"]="Le configurazioni INI e del menu sono indipendenti. I tasti del menu sono inizialmente liberi: assegnali nella scheda MODS. Cambiare fonte non sovrascrive nulla.",["hint"]="INI attivo. Seleziona ModBindingsMenu come Fonte dei tasti per usare queste impostazioni.",["seat1"]="Posto 1: conducente",["seat2"]="Posto 2: passeggero anteriore / artigliere",["seat3"]="Posto 3: posteriore sinistro / passeggero sinistro / lanciafiamme",["seat4"]="Posto 4: posteriore destro / passeggero destro",["seat5"]="Posto 5: mitragliere M-102"}},["es"]={["mod"]="vehicle_specified_seat_switch",["language"]="es",["strings"]={["mode"]="Versión",["normal"]="Normal",["enhanced"]="Mejorada",["strategy"]="Origen de los controles",["mode_description"]="Normal mantiene los grupos de asientos originales. Mejorada permite cambiar entre grupos en solitario y multijugador. Los cambios se aplican al terminar el cambio de asiento actual.",["keys_description"]="INI y menú guardan configuraciones independientes. Los controles del menú empiezan sin asignar: configúralos en MODS. Cambiar el origen no sobrescribe ninguna configuración.",["hint"]="INI activo. Selecciona ModBindingsMenu en Origen de los controles para usar estos ajustes.",["seat1"]="Asiento 1: conductor",["seat2"]="Asiento 2: copiloto / artillero",["seat3"]="Asiento 3: trasero izquierdo / pasajero izquierdo / lanzallamas",["seat4"]="Asiento 4: trasero derecho / pasajero derecho",["seat5"]="Asiento 5: ametrallador del M-102"}},["es-419"]={["mod"]="vehicle_specified_seat_switch",["language"]="es-419",["strings"]={["mode"]="Versión",["normal"]="Normal",["enhanced"]="Mejorada",["strategy"]="Origen de los controles",["mode_description"]="Normal conserva los grupos de asientos originales. Mejorada permite cambiar entre grupos en solitario y multijugador. Los cambios se aplican al terminar el cambio de asiento actual.",["keys_description"]="INI y menú guardan configuraciones independientes. Los controles del menú empiezan sin asignar: configúralos en MODS. Cambiar el origen no sobrescribe ninguna configuración.",["hint"]="INI activo. Selecciona ModBindingsMenu en Origen de los controles para usar estos ajustes.",["seat1"]="Asiento 1: conductor",["seat2"]="Asiento 2: copiloto / artillero",["seat3"]="Asiento 3: trasero izquierdo / pasajero izquierdo / lanzallamas",["seat4"]="Asiento 4: trasero derecho / pasajero derecho",["seat5"]="Asiento 5: ametrallador del M-102"}},["pt-BR"]={["mod"]="vehicle_specified_seat_switch",["language"]="pt-BR",["strings"]={["mode"]="Versão",["normal"]="Normal",["enhanced"]="Aprimorada",["strategy"]="Origem das teclas",["mode_description"]="Normal mantém os grupos de assentos originais. Aprimorada permite trocar entre grupos no modo solo e multijogador. As mudanças aguardam o fim da troca de assento atual.",["keys_description"]="INI e menu salvam configurações independentes. As teclas do menu começam sem atribuição: configure-as em MODS. Trocar a origem não sobrescreve configurações.",["hint"]="INI ativo. Escolha ModBindingsMenu em Origem das teclas para usar estas configurações.",["seat1"]="Assento 1: motorista",["seat2"]="Assento 2: passageiro dianteiro / artilheiro",["seat3"]="Assento 3: traseiro esquerdo / passageiro esquerdo / lança-chamas",["seat4"]="Assento 4: traseiro direito / passageiro direito",["seat5"]="Assento 5: metralhador do M-102"}},["pl"]={["mod"]="vehicle_specified_seat_switch",["language"]="pl",["strings"]={["mode"]="Wersja",["normal"]="Zwykła",["enhanced"]="Rozszerzona",["strategy"]="Źródło przypisań",["mode_description"]="Zwykła zachowuje grupy miejsc z gry. Rozszerzona pozwala zmieniać grupy w grze solo i wieloosobowej. Ustawienia zmienią się po zakończeniu bieżącej zmiany miejsca.",["keys_description"]="INI i menu zapisują przypisania niezależnie. Klawisze menu są początkowo nieprzypisane: ustaw je w MODS. Zmiana źródła nie nadpisuje przypisań.",["hint"]="INI aktywne. Wybierz ModBindingsMenu jako Źródło przypisań, aby użyć tych ustawień.",["seat1"]="Miejsce 1: kierowca",["seat2"]="Miejsce 2: pasażer z przodu / strzelec",["seat3"]="Miejsce 3: tył lewy / lewy pasażer / miotacz ognia",["seat4"]="Miejsce 4: tył prawy / prawy pasażer",["seat5"]="Miejsce 5: strzelec karabinu M-102"}},["ru"]={["mod"]="vehicle_specified_seat_switch",["language"]="ru",["strings"]={["mode"]="Версия",["normal"]="Обычная",["enhanced"]="Улучшенная",["strategy"]="Источник назначений",["mode_description"]="Обычная сохраняет штатные группы мест. Улучшенная позволяет переходить между группами в одиночной и сетевой игре. Настройки применяются после завершения текущей смены места.",["keys_description"]="INI и меню хранят назначения независимо. В меню клавиши изначально не назначены: настройте их на вкладке MODS. Переключение источника не перезаписывает назначения.",["hint"]="Активен INI. Для этих назначений выберите ModBindingsMenu в «Источник назначений».",["seat1"]="Место 1: водитель",["seat2"]="Место 2: передний пассажир / стрелок",["seat3"]="Место 3: сзади слева / левый пассажир / огнемёт",["seat4"]="Место 4: сзади справа / правый пассажир",["seat5"]="Место 5: пулемётчик M-102"}}}}
